import re,os
import pages as PG
from pages import P,paras,key,T,reading,cards,glance,SHARE
from lib import head, cover
from fig import *
SL='/how-to-read-iast/'
def letters(pairs,w=560,h=150,cols=None):
    o=''; n=len(pairs); cw=w/n
    for k,(a,b) in enumerate(pairs):
        x=cw*k+cw/2
        o+=f'<rect x="{x-cw/2+6:.0f}" y="18" width="{cw-12:.0f}" height="{h-36}" rx="10" fill="#fff" stroke="#111" stroke-width="2.5"/>'
        o+=f'<text x="{x:.0f}" y="{h/2+8:.0f}" text-anchor="middle" font-family="Georgia,serif" font-size="40" font-weight="700" fill="#0b2a4a">{a}</text>'+lab(x,h-28,b,11)
    return o
def mouth(hi=None,labels=True):
    pts=[('velar',360,70,'k kh g gh ṅ'),('palatal',300,58,'c ch j jh ñ'),('retroflex',250,64,'ṭ ṭh ḍ ḍh ṇ'),('dental',175,96,'t th d dh n'),('labial',140,120,'p ph b bh m')]
    o='<path d="M130 140 q-10 -40 20 -60 q60 -40 160 -36 q80 4 110 50 q10 20 0 60 l-60 30 h-220z" fill="#fde4e4" stroke="#111" stroke-width="3"/>'
    o+='<path d="M150 104 q40 -8 70 0 q60 20 130 0" fill="none" stroke="#111" stroke-width="2"/><path d="M160 150 q80 -60 200 -10 q20 10 10 30 h-210z" fill="#f08a98" stroke="#111" stroke-width="2.5"/>'
    for nm,x,y,l in pts:
        c='#c0392b' if nm==hi else '#1d4f9a'
        o+=f'<circle cx="{x}" cy="{y}" r="7" fill="{c}" stroke="#111" stroke-width="2"/>'
    if labels: o+=''.join(lab(480,30+k*30,f'{nm}: {l}',11).replace('text-anchor="middle"','text-anchor="start"').replace('x="480"','x="440"') for k,(nm,x,y,l) in enumerate(pts))
    return o
COV=f'<svg class="coverart" width="440" height="220" viewBox="0 0 440 220" role="img" aria-label="Large letters with diacritics: ā, ṛ, ṣ, ṇ and ṃ on cards, with a speech bubble"><rect width="440" height="220" rx="10" fill="#e3eaf3"/>'+letters([('ā','long a'),('ṛ','vowel r'),('ṣ','retroflex sh'),('ṇ','retroflex n'),('ṃ','nasal hum')],440,200)+'</svg>'
pages=[]
pages.append(P('foreword','WHY THIS GUIDE','','<div class="panel bg-blue halftone" style="font-size:17px;line-height:1.6"><p>Every hymn and verse on this site is written in <b>IAST</b>, the International Alphabet of Sanskrit Transliteration: ordinary Roman letters with a few dots and lines added. We use it instead of Devanāgarī so that anyone can read the Sanskrit, whatever script they grew up with.</p><p>But the dots and lines matter. <i>Śiva</i> and <i>siva</i>, <i>Kālī</i> and <i>kali</i> are different words. This guide explains every special letter in plain English, with examples you already know, so you can chant from our pages with confidence.</p><p>Read it once, then keep it open beside any verse page.</p><p style="text-align:right;margin-top:14px"><span class="bang" style="font-size:22px;color:#0b2a4a">With the blessings of the Lord,</span><br><span class="bang" style="font-size:26px">srini.presents</span> 🙏</p></div>'+T(('z','Why not just write “Shiva” and “Krishna”?'),('b','Because “sh” could be ś or ṣ, and “ri” hides the vowel ṛ. IAST tells you exactly how to say each sound, with one letter per sound.'))))
pages.append(glance([('ā ī ū','Long vowels: hold them twice as long as a i u'),('e o ai au','Always long in Sanskrit: e as in “café”, o as in “go”'),('ṛ ṝ ḷ','Vowel r (and l): a short “ri” (north) or “ru” (south)'),('ṭ ṭh ḍ ḍh ṇ','Retroflex: tongue tip curled back to the roof of the mouth'),('t th d dh n','Dental: tongue tip touching the back of the upper teeth'),('kh gh ch jh th dh ph bh','Aspirated: the same sound plus a puff of breath; th is not English “th”, ph is not “f”'),('c','Always “ch” as in “church”: candra = chandra'),('ś ṣ s','Three hisses: ś soft “sh”, ṣ hard retroflex “sh”, s as in “sun”'),('ṅ ñ','Nasals: ṅ as in “sing”, ñ as in Spanish “señor”'),('ṃ ḥ','Anusvāra (a nasal hum) and visarga (a soft breath, echoing the vowel)')],
  PG.svg(560,130,'All the special letters in a row',letters([('ā','long'),('ṛ','vowel r'),('ṭ','curled'),('ś','soft sh'),('ṣ','hard sh'),('ñ','ny'),('ṃ','hum'),('ḥ','breath')],560,130)) if hasattr(PG,'svg') else svg(560,130,'All the special letters in a row',letters([('ā','long'),('ṛ','vowel r'),('ṭ','curled'),('ś','soft sh'),('ṣ','hard sh'),('ñ','ny'),('ṃ','hum'),('ḥ','breath')],560,130)),
  [('z','That’s a lot of dots.'),('b','Only about a dozen new marks. Learn them once and every verse on the site opens up.')]))
pages.append(reading('vowels','LONG AND SHORT VOWELS','The line on top means “hold it”',svg(560,150,'Pairs of short and long vowels with bars showing the long ones twice as long',letters([('a','short'),('ā','long'),('i','short'),('ī','long'),('u','short'),('ū','long')],560,150)),[
 '<b>The macron.</b> A line over a vowel (ā, ī, ū) means it is <b>long</b>: held for about twice as long as the short one. That is all; the sound itself barely changes.','<b>The sounds.</b> <b>a</b> is short, like the “u” in “but”; <b>ā</b> is long, like “a” in “father”. <b>i</b> as in “bit”, <b>ī</b> as in “machine”. <b>u</b> as in “put”, <b>ū</b> as in “rule”.','<b>Always long.</b> <b>e</b> (as in “café”) and <b>o</b> (as in “go”) have no short form in Sanskrit, so they carry no mark. <b>ai</b> sounds as in “aisle”, <b>au</b> as in “loud”.','<b>Why it matters.</b> Length changes meaning and rhythm. <i>Kālī</i> (the Goddess) is not <i>kali</i> (the dark age). In a verse, long syllables carry the beat, so getting them right makes a chant flow.'],
 [('z','So Rāma is “Raa-ma”?'),('b','Yes: a long first “a”, a short final one. And Śiva is “Shi-va”, both short.')],'A line on top means <b>hold the vowel twice as long</b>.'))
pages.append(reading('r','THE VOWEL Ṛ','Not a consonant, a vowel',svg(560,150,'The words Kṛṣṇa, ṛṣi and amṛta with the vowel ṛ highlighted',''.join(f'<text x="{x}" y="90" text-anchor="middle" font-family="Georgia,serif" font-size="34" font-weight="700" fill="#0b2a4a">{w}</text>' for x,w in [(110,'Kṛṣṇa'),(280,'ṛṣi'),(450,'amṛta')])+lab(110,125,'Krishna')+lab(280,125,'rishi, sage')+lab(450,125,'nectar')),[
 '<b>A vowel.</b> <b>ṛ</b>, with a dot under it, is a <b>vowel</b>, not a consonant: a short, rolled “r” that carries a syllable by itself, like the “r” some people say in “purr”.','<b>Two common ways.</b> In North India it is usually said like a short “ri” (<i>Krishna, rishi</i>); in much of South India like a short “ru” (<i>Krushna</i>, <i>amrutha</i>). Both are traditional; follow your teacher or family.','<b>Long ṝ and ḷ.</b> <b>ṝ</b> is the same held longer, and <b>ḷ</b> is a rare vowel “l” (like a short “lri”). You will meet them only occasionally.','<b>Spot it.</b> Kṛṣṇa, ṛṣi, amṛta, Bṛhaspati, hṛdaya (heart), Vṛṣabha (bull): every one has the vowel ṛ.'],
 [('z','So Kṛṣṇa has no “i” in it?'),('b','Not written. The ṛ is the vowel. The “i” or “u” you hear is just how the vowel is voiced.')],'<b>ṛ is a vowel</b>: “ri” in the north, “ru” in the south.'))
pages.append(reading('mouth','WHERE THE SOUNDS ARE MADE','Five places in the mouth',svg(560,200,'A side view of the mouth with five points marked: back (velar), palate, roof curled (retroflex), teeth (dental) and lips (labial), each with its letters',mouth()),[
 '<b>A beautiful order.</b> Sanskrit grammarians arranged the consonants by where the tongue or lips touch, from the throat forward: <b>velar</b> (back), <b>palatal</b> (palate), <b>retroflex</b> (roof, tongue curled), <b>dental</b> (teeth), <b>labial</b> (lips).','<b>Five in each row.</b> Each place has five: plain, breathy (aspirated), voiced, voiced breathy, and nasal. So <b>k kh g gh ṅ</b>, <b>c ch j jh ñ</b>, <b>ṭ ṭh ḍ ḍh ṇ</b>, <b>t th d dh n</b>, <b>p ph b bh m</b>.','<b>Why learn it.</b> Once you know the five places, every dotted letter makes sense: the dots mark the retroflex row, and the h’s mark breath.','<b>Try it.</b> Say ka, ca, ṭa, ta, pa slowly and feel the touch move forward from the back of your mouth to your lips.'],
 [('z','Grammarians drew a map of the mouth?'),('b','Over two thousand years ago, and it is still the best way to learn the sounds.')],'Back, palate, roof, teeth, lips: <b>the consonants in five rows</b>.'))
pages.append(reading('dots','DOTS UNDER T, D, N','Retroflex versus dental',svg(560,180,'Two mouth diagrams: on the left the tongue curled back for ṭ, on the right touching the teeth for t',g(-30,20,.75,mouth('retroflex',False))+lab(140,170,'ṭ ḍ ṇ: tongue curled back')+g(250,20,.75,mouth('dental',False))+lab(420,170,'t d n: tongue at the teeth')),[
 '<b>Dotted = curled.</b> <b>ṭ ṭh ḍ ḍh ṇ</b> (and ṣ) are <b>retroflex</b>: curl the tip of your tongue back and touch the roof of your mouth. They sound heavy, like the “t” in Indian English “time”.','<b>Plain = teeth.</b> <b>t th d dh n</b> are <b>dental</b>: the tongue tip touches the back of the upper teeth. They sound soft, like the “t” in Spanish or French.','<b>English is in between.</b> English “t” and “d” sit between the two, so English speakers need to push one way or the other.','<b>Examples.</b> Gaṇeśa, Kṛṣṇa, maṇḍapa, Naṭarāja (retroflex); deva, tat tvam asi, Nandi (dental).'],
 [('z','Does it really make a difference?'),('b','To meaning, yes. And to a chant’s sound: the curled letters give Sanskrit its weight.')],'Dot underneath: <b>curl the tongue back</b>. No dot: <b>tongue to the teeth</b>.'))
pages.append(reading('breath','THE H THAT IS BREATH','kh, gh, th, dh, ph, bh…',svg(560,160,'A letter t followed by a small puff of air drawn as a cloud, showing th as t plus breath, not English th',f'<text x="150" y="100" font-family="Georgia,serif" font-size="56" font-weight="700" fill="#0b2a4a">t</text>'+'<path d="M190 80 q20 -20 40 0 q20 -10 30 10 q-30 20 -70 -10z" fill="#fff" stroke="#111" stroke-width="2"/>'+lab(220,130,'t + a puff of breath')+f'<text x="360" y="100" font-family="Georgia,serif" font-size="40" fill="#c0392b">≠ “the”</text>'),[
 '<b>An h means a puff.</b> In IAST, an <b>h</b> after a consonant is <b>breath</b>: the same sound with a puff of air. Hold your hand before your mouth: you should feel it on <b>kh</b> but hardly on <b>k</b>.','<b>th is not “the”.</b> <b>th</b> is a breathy “t” as in “hot tea” said quickly; it is never the English “th” of “thin” or “this”. So <i>Ratha</i> is “rat-ha”, and <i>tathāgata</i> is “tat-haa-ga-ta”.','<b>ph is not “f”.</b> <b>ph</b> is a breathy “p”, as in “top hat”, not “f”. <i>Phala</i> (fruit) is “p-hala”.','<b>Voiced ones too.</b> <b>gh, jh, ḍh, dh, bh</b> are voiced with breath: <i>Bhagavad Gītā</i>, <i>dharma</i>, <i>Siddhidātrī</i>.'],
 [('z','So “Bhagavad” starts with a b-h?'),('b','A b with a breath behind it, all in one sound. Not “b” then “h”.')],'<b>h after a consonant = a puff of breath</b>; th ≠ English th, ph ≠ f.'))
pages.append(cards('hiss','C, Ś, Ṣ AND S','The “ch” and the three hisses',svg(560,150,'Four letter cards: c as ch, ś as soft sh, ṣ as hard sh and s as s',letters([('c','“ch”'),('ś','soft sh'),('ṣ','hard sh'),('s','s')],560,150)),[
 ('🅲','c is always “ch”','<b>c</b> is never “k” or “s”. <i>Candra</i> is “chandra”, <i>Cāmuṇḍā</i> “Chaamundaa”, and <b>ch</b> is the same with breath (<i>chāyā</i>, shadow).'),
 ('🌙','ś: the soft sh','<b>ś</b> (acute accent) is a palatal “sh”, as in “ship” with the tongue near the palate: <i>Śiva, Śrī, Śaṅkara</i>.'),
 ('🌀','ṣ: the hard sh','<b>ṣ</b> (dot under) is a retroflex “sh”, tongue curled back: <i>Viṣṇu, Kṛṣṇa, Lakṣmī, ṛṣi</i>. Many speakers make little difference between ś and ṣ; careful chanters do.'),
 ('🐍','s: plain s','<b>s</b> is just “s”, as in “sun”: <i>Sarasvatī, Sītā, sūrya</i>.')],
 [('z','So Śiva and Viṣṇu both have “sh”, but different ones?'),('b','Exactly. Śiva’s is soft, from the palate; Viṣṇu’s is hard, tongue curled. Now you can hear it.')],'<b>c = ch</b>; ś soft sh, ṣ hard sh, s plain s.'))
pages.append(reading('nasal','ṄA, ÑA, Ṃ AND Ḥ','Nasals, the hum and the breath at the end',svg(560,160,'The words śaṅkha, jñāna, oṃ and namaḥ written large with the special letter highlighted',''.join(f'<text x="{x}" y="85" text-anchor="middle" font-family="Georgia,serif" font-size="32" font-weight="700" fill="#0b2a4a">{w}</text>'+lab(x,120,m) for x,w,m in [(80,'śaṅkha','conch'),(210,'jñāna','knowledge'),(340,'oṃ','the sacred syllable'),(470,'namaḥ','bowing')])),[
 '<b>ṅ and ñ.</b> <b>ṅ</b> is the “ng” of “sing” (<i>Gaṅgā, śaṅkha</i>). <b>ñ</b> is the “ny” of Spanish “señor” (<i>pañca</i>, five; <i>vāñchita</i>). The cluster <b>jñ</b>, as in <i>jñāna</i>, is said “gnya” or “dnya” in different regions; traditions differ.','<b>ṃ, the anusvāra.</b> A dot under (or above) m marks a nasal hum that takes the colour of the next sound: <i>saṃskṛta</i>, <i>śailaputrīṃ</i>. At the end of a line it is a soft “m”. Older books may print it ṁ; we use ṃ.','<b>ḥ, the visarga.</b> <b>ḥ</b> at the end of a word is a soft breath that echoes the vowel before it: <i>namaḥ</i> is “namaha”, <i>śāntiḥ</i> “shaantihi”, said lightly.','<b>Together.</b> <i>Oṃ namaḥ śivāya</i>: a hum, a breath, a soft sh, a long ā. You can now read it exactly.'],
 [('z','So I should say “namaha”, not “namah”?'),('b','A light echo: “nama-ha”, with the last “a” barely there. It shouldn’t sound like a new syllable shouted.')],'<b>ṅ = ng, ñ = ny, ṃ = hum, ḥ = breath echo</b>.'))
pages.append(PG.verse('practice','PRACTICE','NAVADURGĀ STOTRA 1, SYLLABLE BY SYLLABLE',['vande vāñchitalābhāya candrārdhakṛtaśekharām .','vṛṣārūḍhāṃ śūladharāṃ śailaputrīṃ yaśasvinīm ..'],svg(220,160,'Śailaputrī on her bull, the goddess of this practice verse',g(100,150,.8,beast('bull'))+g(110,120,.65,devi(sari='#f4f1ea',items=('trident','lotus'),moon_c=True)),cls=''),
 'Said slowly: <b>van-de vaañ-chi-ta-laa-bhaa-ya chan-draar-dha-kru-ta-she-kha-raam · vru-shaa-ruu-dhaam shuu-la-dha-raam shai-la-put-riim ya-shas-vi-niim</b>. (Long vowels doubled here only to show length.)',
 [('vāñchita','long ā, then ñ before ch'),('candra','c = ch; dental d'),('kṛta','vowel ṛ: “kri” or “kru”'),('śekharām','soft ś; kh with breath'),('vṛṣārūḍhām','vowel ṛ, hard ṣ, long ā and ū, curled ḍh, hum ṃ')],
 '<b>Read it three ways.</b> First slowly, syllable by syllable; then at a steady pace, giving long syllables their full beat; then as a chant. The meaning and the full page are in our <a href="/festivals/navaratri/shailaputri/">Śailaputrī article</a>.',None,'Slow, steady, chanted: <b>three readings and the letters become sound</b>.','Text as in the Navadurgā Stotra (shlokam.org transliteration).'))
pages.append(P('end','ON ONE PAGE','The whole guide in five lines','<div class="steps">'+''.join(f'<div>{l}</div>' for l in ['<b>Line on top</b> (ā ī ū): hold the vowel twice as long; e and o are always long.','<b>ṛ</b> is a vowel: “ri” or “ru”.','<b>Dot underneath</b> (ṭ ḍ ṇ ṣ): curl the tongue back. No dot: tongue to the teeth.','<b>h after a consonant</b> is a puff of breath; <b>c</b> is always “ch”; ś soft sh, ṣ hard sh.','<b>ṅ</b> = ng, <b>ñ</b> = ny, <b>ṃ</b> = hum, <b>ḥ</b> = soft breath echo.'])+'</div>'+T(('z','Where do I use this?'),('b','On every verse page of the site: the <a href="/devi/devi-mahatmya/">Devī Māhātmya</a>, the <a href="/vishnu/bhagavad-gita/">Gītā</a>, the <a href="/festivals/navaratri/">Navarātri</a> verses and all the hymns. Keep this page open beside them.')) +key('How to read IAST: <b>a dozen marks, every verse opened</b>. Start with the <a href="/festivals/navaratri/">Navarātri series</a>.')))
pages.append(P('sources','SOURCES &amp; NOTES','Where the facts come from',paras(['<b>Conventions:</b> IAST as standardised for Sanskrit (Geneva, 1894) and its successor ISO 15919; the five places of articulation as set out in the Sanskrit phonetic tradition (śikṣā) and in Pāṇinian grammar. Wikipedia, “International Alphabet of Sanskrit Transliteration”, “Sanskrit phonology”.','<b>Sources differ:</b> regional pronunciations of ṛ (ri / ru), jñ (gya / dnya / jnya), the visarga echo, and how strongly ś and ṣ are distinguished. We give the common options; follow your teacher.'],'panel reading small')+'<p class="studynotes"><b>Study notes:</b> Pronunciations are approximations through English and should be checked by listening to a good chanter. Zappy and Prof. Bolt are fictional.</p>'))
items=[]
for p in pages:
    m=re.search(r'<section class="page" id="([^"]+)">.*?<h2 class="page-title">(.*?)</h2>',p,re.S)
    if m: items.append((m.group(1),m.group(2).title().replace('&Amp;','&amp;')))
hd=head('How to Read IAST: A Pronunciation Guide for Sanskrit Verses · srini.presents','How to read IAST, the transliteration used for every Sanskrit verse on this site: long vowels, the vowel ṛ, retroflex and dental letters, aspirates, c, ś, ṣ and s, the nasals, anusvāra ṃ and visarga ḥ, with a practice verse. An illustrated pronunciation guide.','https://bhakti.srinipresents.com'+SL,red=False).replace('<link rel="stylesheet" href="/assets/editorial/article-cover.css?v=2">','')
cv=cover('BEFORE YOU CHANT · ā ṛ ṣ ṇ ṃ ḥ','How to Read IAST','The dots and lines in every Sanskrit verse · explained and illustrated',COV,'A dozen marks, every verse opened','First <b>why we use IAST</b>, then each special letter with <b>examples you already know</b>: long vowels, the vowel ṛ, the dotted letters, breath, the three hisses, the nasals, and a <b>practice verse</b>.')
html=hd+'<div class="book">\n'+'\n\n'.join([cv,pages[0],PG.contents(items[1:])]+pages[1:])+'\n</div>\n'+SHARE+'\n</body>\n</html>\n'
os.makedirs('iast_out/how-to-read-iast',exist_ok=True)
open('iast_out/how-to-read-iast/index.html','w').write(html)
inner=re.search(r'<svg class="coverart"[^>]*>(.*)</svg>',COV,re.S).group(1)
open('iast_out/how-to-read-iast/cover.svg','w').write(f'<svg xmlns="http://www.w3.org/2000/svg" width="380" height="268" viewBox="0 0 380 268"><rect width="380" height="268" fill="#e3eaf3"/><g transform="translate(0 24) scale(.8636)">{inner}</g></svg>')
print('ok')
